class Car:
    def __init__(self, make, model, year):
        self.__make = make
        self.__model = model
        self.__year = year

    def getCarAge(self, current_year):
        if self.__year > current_year:
            return -1
        return current_year - self.__year

def main():
    make = input().strip()
    model = input().strip()
    year = int(input().strip())
    current_year = int(input().strip())

    car = Car(make, model, year)
    age = car.getCarAge(current_year)

    if age == -1:
        print("Invalid year")
    else:
        print(age)

if __name__ == "__main__":
    main()
